class Solution {
  private static final long NONE = Long.MIN_VALUE / 4;

  public long maximumValueSum(int[][] board) {
    int m = board.length;
    long[][] val = new long[m][3];
    int[][] col = new int[m][3];
    for (int i = 0; i < m; i++) top3(board[i], val[i], col[i]);
    long[][] preVal = new long[m + 1][3], sufVal = new long[m + 1][3];
    int[][] preCol = new int[m + 1][3], sufCol = new int[m + 1][3];
    for (long[] a : preVal) Arrays.fill(a, NONE);
    for (long[] a : sufVal) Arrays.fill(a, NONE);
    for (int i = 0; i < m; i++) {
      merge(preVal[i], preCol[i], val[i], col[i], preVal[i + 1], preCol[i + 1]);
    }
    for (int i = m - 1; i >= 0; i--) {
      merge(sufVal[i + 1], sufCol[i + 1], val[i], col[i], sufVal[i], sufCol[i]);
    }
    long best = Long.MIN_VALUE;
    for (int b = 1; b + 1 < m; b++) {
      for (int x = 0; x < 3; x++) {
        if (val[b][x] == NONE) continue;
        for (int y = 0; y < 3; y++) {
          if (preVal[b][y] == NONE || preCol[b][y] == col[b][x]) continue;
          for (int z = 0; z < 3; z++) {
            if (sufVal[b + 1][z] == NONE) continue;
            if (sufCol[b + 1][z] == col[b][x] || sufCol[b + 1][z] == preCol[b][y]) continue;
            best = Math.max(best, val[b][x] + preVal[b][y] + sufVal[b + 1][z]);
          }
        }
      }
    }
    return best;
  }

  // three largest values of a row with their columns
  private void top3(int[] row, long[] val, int[] col) {
    Arrays.fill(val, NONE);
    Arrays.fill(col, -1);
    for (int j = 0; j < row.length; j++) {
      long v = row[j];
      for (int p = 0; p < 3; p++) {
        if (v > val[p]) {
          for (int q = 2; q > p; q--) {
            val[q] = val[q - 1];
            col[q] = col[q - 1];
          }
          val[p] = v;
          col[p] = j;
          break;
        }
      }
    }
  }

  // best three values, one per column, among the two candidate lists
  private void merge(long[] v1, int[] c1, long[] v2, int[] c2, long[] outVal, int[] outCol) {
    Arrays.fill(outVal, NONE);
    Arrays.fill(outCol, -1);
    for (int pass = 0; pass < 2; pass++) {
      long[] v = pass == 0 ? v1 : v2;
      int[] c = pass == 0 ? c1 : c2;
      for (int i = 0; i < 3; i++) {
        if (v[i] == NONE) continue;
        int existing = -1;
        for (int p = 0; p < 3; p++) if (outVal[p] != NONE && outCol[p] == c[i]) existing = p;
        if (existing >= 0 && outVal[existing] >= v[i]) continue;
        if (existing >= 0) {
          outVal[existing] = NONE;
          outCol[existing] = -1;
        }
        insert(outVal, outCol, v[i], c[i]);
      }
    }
  }

  private void insert(long[] val, int[] col, long v, int c) {
    for (int p = 0; p < 3; p++) {
      if (v > val[p]) {
        for (int q = 2; q > p; q--) {
          val[q] = val[q - 1];
          col[q] = col[q - 1];
        }
        val[p] = v;
        col[p] = c;
        return;
      }
    }
  }
}
